'use strict';

const ADMIN_BUNDLE_BASE64 = '';
const DEFAULT_PUBLISHABLE_KEY = 'sb_publishable_yj_yBwVhaUPj7nQdcFDxrg_g_ukcwTX';

function config() {
  return {
    url: String(process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://cxkevnnxibhezvospkce.supabase.co').replace(/\/$/, ''),
    publishableKey: process.env.SUPABASE_ANON_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || DEFAULT_PUBLISHABLE_KEY
  };
}

async function json(response) {
  const text = await response.text();
  if (!text) return null;
  try { return JSON.parse(text); } catch (_) { return null; }
}

module.exports = async function protectedAdminRuntime(req, res) {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.setHeader('Allow', 'GET, HEAD');
    return res.status(405).end();
  }

  res.setHeader('Cache-Control', 'private, no-store, max-age=0');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Vary', 'Authorization');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Robots-Tag', 'noindex, nofollow, noarchive');

  const authorization = String(req.headers.authorization || '');
  const token = authorization.startsWith('Bearer ') ? authorization.slice(7).trim() : '';
  if (!token) return res.status(404).end();

  const origin = String(req.headers.origin || '');
  const host = String(req.headers.host || '');
  if (origin) {
    try {
      if (new URL(origin).host !== host) return res.status(404).end();
    } catch (_) { return res.status(404).end(); }
  }

  try {
    const { url, publishableKey } = config();
    const userResponse = await fetch(`${url}/auth/v1/user`, {
      headers: { apikey: publishableKey, Authorization: `Bearer ${token}` }
    });
    const user = await json(userResponse);
    if (!userResponse.ok || !user?.id) return res.status(404).end();

    const adminResponse = await fetch(`${url}/rest/v1/rpc/is_admin`, {
      method: 'POST',
      headers: {
        apikey: publishableKey,
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: '{}'
    });
    const allowed = await json(adminResponse);
    if (!adminResponse.ok || allowed !== true) return res.status(404).end();

    res.setHeader('Content-Type', 'application/javascript; charset=utf-8');
    if (req.method === 'HEAD') return res.status(200).end();
    return res.status(200).send(Buffer.from(ADMIN_BUNDLE_BASE64, 'base64'));
  } catch (_) {
    return res.status(404).end();
  }
};
